import { test } from "node:test";
import assert from "node:assert/strict";
import { TodoList } from "../src/todo.js";

test("ids are unique", () => {
  const list = new TodoList();
  const a = list.add("buy milk");
  const b = list.add("walk dog");
  assert.notEqual(a.id, b.id);
});

test("pending lists only open items", () => {
  const list = new TodoList();
  const a = list.add("buy milk");
  list.add("walk dog");
  list.complete(a.id);
  assert.deepEqual(list.pending().map(i => i.title), ["walk dog"]);
});

test("completing an unknown id throws", () => {
  const list = new TodoList();
  assert.throws(() => list.complete(42), /not found/);
});

test("clear removes completed items", () => {
  const list = new TodoList();
  const a = list.add("buy milk");
  list.add("walk dog");
  list.complete(a.id);
  list.clear();
  assert.deepEqual(list.items.map(i => i.title), ["walk dog"]);
});

