#!/usr/bin/env node
// Usage: todo add <title> [--due DATE] [--priority low|normal|high]
//        todo done <id>
//        todo list
// The list is stored in $TODO_FILE (default: ./todo.json).
import { existsSync } from "node:fs";
import { TodoList } from "../src/todo.js";

const file = process.env.TODO_FILE ?? "todo.json";
const [cmd, ...args] = process.argv.slice(2);

function fail(msg) {
  console.error(msg);
  process.exit(1);
}

const list = existsSync(file) ? TodoList.load(file) : new TodoList();

try {
  if (cmd === "add") {
    const opts = {};
    const words = [];
    for (let i = 0; i < args.length; i++) {
      if (args[i] === "--due") opts.due = args[++i];
      else if (args[i] === "--priority") opts.priority = args[++i];
      else words.push(args[i]);
    }
    const item = list.add(words.join(" "), opts);
    list.save(file);
    console.log(`added ${item.id}: ${item.title}`);
  } else if (cmd === "done") {
    const item = list.complete(Number(args[0]));
    list.save(file);
    console.log(`completed ${item.id}: ${item.title}`);
  } else if (cmd === "list") {
    for (const i of list.sorted()) {
      const due = i.due ? ` (due ${i.due.slice(0, 10)})` : "";
      console.log(`${i.id} [${i.done ? "x" : " "}] ${i.priority} ${i.title}${due}`);
    }
  } else {
    fail("usage: todo add <title> [--due DATE] [--priority P] | done <id> | list");
  }
} catch (e) {
  fail(e.message);
}

