test("add stores due date and priority with defaults", () => {
  const list = new TodoList();
  const a = list.add("a");
  const b = list.add("b", { due: "2026-01-02", priority: "high" });
  assert.equal(a.due, null);
  assert.equal(a.priority, "normal");
  assert.equal(b.due, new Date("2026-01-02").toISOString());
  assert.equal(b.priority, "high");
});

test("add rejects bad priority and bad due date", () => {
  const list = new TodoList();
  assert.throws(() => list.add("a", { priority: "urgent" }), /invalid priority/);
  assert.throws(() => list.add("a", { due: "nonsense" }), /invalid due date/);
});

test("sorted orders overdue, then priority, then due date", () => {
  const list = new TodoList();
  const now = new Date("2026-06-01");
  list.add("none-normal");
  list.add("future-high", { due: "2026-07-01", priority: "high" });
  list.add("future-normal-late", { due: "2026-09-01" });
  list.add("future-normal-soon", { due: "2026-08-01" });
  list.add("overdue-low", { due: "2026-05-01", priority: "low" });
  list.add("overdue-high", { due: "2026-05-15", priority: "high" });
  const done = list.add("overdue-done", { due: "2026-04-01", priority: "high" });
  list.complete(done.id);
  assert.deepEqual(list.sorted(now).map(i => i.title), [
    "overdue-high", "overdue-low",
    "future-high", "overdue-done",
    "future-normal-soon", "future-normal-late", "none-normal",
  ]);
});

test("sorted does not mutate the list", () => {
  const list = new TodoList();
  list.add("a");
  list.add("b", { priority: "high" });
  list.sorted();
  assert.deepEqual(list.items.map(i => i.title), ["a", "b"]);
});

test("save and load round-trip", () => {
  const dir = mkdtempSync(join(tmpdir(), "todo-"));
  const path = join(dir, "t.json");
  const list = new TodoList();
  list.add("a", { due: "2026-01-02", priority: "low" });
  const b = list.add("b");
  list.complete(b.id);
  list.save(path);
  const loaded = TodoList.load(path);
  assert.deepEqual(loaded.items, list.items);
  assert.equal(loaded.add("c").id, 3);
  rmSync(dir, { recursive: true });
});

test("load fills defaults for old files and keeps ids unique", () => {
  const dir = mkdtempSync(join(tmpdir(), "todo-"));
  const path = join(dir, "t.json");
  writeFileSync(path, JSON.stringify({ items: [{ id: 5, title: "old", done: false }] }));
  const loaded = TodoList.load(path);
  assert.equal(loaded.items[0].priority, "normal");
  assert.equal(loaded.items[0].due, null);
  assert.equal(loaded.add("new").id, 6);
  rmSync(dir, { recursive: true });
});

test("cli add, done, list", () => {
  const dir = mkdtempSync(join(tmpdir(), "todo-"));
  const env = { ...process.env, TODO_FILE: join(dir, "t.json") };
  const run = (...args) => execFileSync("node", ["bin/todo.js", ...args], { env, encoding: "utf8" });
  assert.match(run("add", "buy", "milk", "--priority", "high", "--due", "2099-01-01"), /added 1: buy milk/);
  run("add", "walk dog");
  assert.match(run("done", "2"), /completed 2/);
  const out = run("list").trim().split("\n");
  assert.equal(out.length, 2);
  assert.match(out[0], /^1 \[ \] high buy milk \(due 2099-01-01\)$/);
  assert.match(out[1], /^2 \[x\] normal walk dog$/);
  assert.throws(() => execFileSync("node", ["bin/todo.js", "done", "99"], { env, stdio: "pipe" }));
  rmSync(dir, { recursive: true });
});
